export const beginnerChoiceQuestionCountsByCategory = beginnerChoiceQuestions.reduce(
  (counts, question) => ({
    ...counts,
    [question.category]: (counts[question.category] ?? 0) + 1,
  }),
  {} as Record<BeginnerChoiceQuestion["category"], number>,
);
